import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d as h,i as b,S as d}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"群、环、域直觉","description":"","frontmatter":{"title":"群、环、域直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/group-ring-field.md","filePath":"cs/group-ring-field.md","lastUpdated":1789023840000}'),p={name:"cs/group-ring-field.md"};function m(c,a,E,_,A,u){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="群、环、域直觉" tabindex="-1">群、环、域直觉 <a class="header-anchor" href="#群、环、域直觉" aria-label="Permalink to &quot;群、环、域直觉&quot;">​</a></h1><div class="epigraph"><p>群管可逆合成；环加一套乘法分配；域让四则都可做。密码学选的是具体群（模 $p$ 乘群、椭圆曲线），不是抽象公理课。</p><footer>—— 据 Artin, Algebra；Ireland and Rosen 整理</footer></div><p>上一课<a href="/cs/crt">CRT</a> 把 \\(\\mathbb{Z}/mn\\mathbb{Z}\\) 写成乘积环。缺口是给结构<strong>命名</strong>：群、环、域，以便后课 \\(\\mathrm{GF}(2^n)\\)、离散对数、椭圆曲线共用一句话「在哪个群里」。不重写同余。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>群 \\((G,\\cdot)\\)：结合、单位、逆。交换则 Abel。\\((\\mathbb{Z}/n\\mathbb{Z})^\\times\\)、椭圆曲线点（后课）是乘/加群。<a href="/cs/boolean-algebra">布尔</a> 的 \\(\\{0,1\\}\\) 加法若取异或也是群。环：加是 Abel 群，乘结合分配，不必有乘逆。域：环且 \\(0\\) 除外都有乘逆。\\(\\mathbb{Z}/n\\mathbb{Z}\\) 是域 \\(\\iff n\\) 素数。有限域阶必 \\(p^k\\)，下一课构造 \\(k\\gt 1\\)。</p><p>同态：保运算。DH 在循环群；RSA 在环 \\(\\mathbb{Z}/n\\mathbb{Z}\\) 的乘。</p><h3 id="不是「把小学算术换名字」" tabindex="-1">不是「把小学算术换名字」 <a class="header-anchor" href="#不是「把小学算术换名字」" aria-label="Permalink to &quot;不是「把小学算术换名字」&quot;">​</a></h3><p>公理用来禁止非法步骤：环上不能除，非交换群不能随便换序。证明「只有一种 \\(p^k\\) 阶域」是后课，本课要判别：眼前对象缺哪条公理。</p><p><span class="marginnote">Artin 的本科代数。本栏只要直觉与例子。Lagrange：有限群子群阶整除 \\(|G|\\)，欧拉定理是其推论，上一课已用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列一张表：\\(\\mathbb{Z}\\) 环非域；\\(\\mathbb{Q}\\) 域；\\(\\mathbb{Z}/6\\mathbb{Z}\\) 环非域；\\(\\mathbb{Z}/5\\mathbb{Z}\\) 域。指出 DH 要循环群生成元，RSA 要环上幂等结构。不要从范畴论起。</p>',11)),(e(),s(d,null,{default:r(()=>[b(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GRP%5B%22%E7%BE%A4%EF%BC%9A%E5%8F%AF%E9%80%86%E5%90%88%E6%88%90%22%5D%20--%3E%20RNG%5B%22%E7%8E%AF%EF%BC%9A%E5%8A%A0%E7%BE%A4%20%2B%20%E4%B9%98%22%5D%0A%20%20RNG%20--%3E%20FLD%5B%22%E5%9F%9F%EF%BC%9A%E4%B9%98%E4%B9%9F%E5%87%A0%E4%B9%8E%E9%83%BD%E5%8F%AF%E9%80%86%22%5D%0A%20%20FLD%20--%3E%20FIN%5B%22%E6%9C%89%E9%99%90%E5%9F%9F%20GF(p%5Ek)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课每个对象先回答：运算是什么、是否可逆、是否交换。离散对数是群上的问题；LWE 在模格上，不是同一公理。本课防止「都是数学」混为一谈。</p><p>有限交换群分解为循环群的积（主理想分解），点名：DH 安全要避开光滑阶。</p><p>Lagrange 推论：元素阶整除 \\(|G|\\)，欧拉定理是 \\((\\mathbb{Z}/n\\mathbb{Z})^\\times\\) 的特例。有限域乘群循环（后课生成元）。非交换群上也可以谈 DH 形状（矩阵群），安全分析不同，本课不进。公理的用处是读协议时先问「除法合法吗」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证分类定理，不引入理想、模。不把椭圆曲线加法公式提前。后课默认：域上四则合法；群上有阶与逆。下一课 \\(\\mathrm{GF}(2^n)\\)。</p><p>先问运算、再问逆、再问交换。域上才能随便除；RSA 模 \\(n\\) 不是域。有限域阶 \\(p^k\\) 的构造下一课从特征 2 写起。公理用来禁止协议里的非法约分。</p><p>上一课留下的缺口在本课收口；「群、环、域直觉」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>群 / 环 / 域差在逆与两条运算。</li><li>\\(\\mathbb{Z}/n\\mathbb{Z}\\) 为域当且仅当 \\(n\\) 素。</li><li>密码学选具体群，公理用来禁止乱除。</li><li>出处：Artin, <em>Algebra</em>；Ireland and Rosen。</li></ul>',10))])}const F=i(p,[["render",m]]);export{g as __pageData,F as default};
